const templates = {
  knowledge:{name:'知识问答助手',project:'科学故事伙伴',question:'天空为什么是蓝色的？',answer:'想象阳光是一盒彩色画笔。阳光穿过空气时，蓝色的光更容易向四周散开，所以抬头时，我们会看到蓝色的天空。',blocks:[['yellow','当收到','用户消息'],['purple','扮演','耐心的科学老师'],['blue','选择模型','演示模型'],['green','查找知识','我的科学知识库'],['cyan','回答','用生活中的例子解释']]},
  work:{name:'工作助手',project:'今日任务伙伴',question:'帮我整理今天的任务。',answer:'可以把今天的任务分成三组：先完成重要且紧急的事，再集中处理沟通，最后为学习留出一段完整时间。',blocks:[['yellow','当收到','工作任务'],['purple','扮演','条理清晰的工作伙伴'],['blue','拆分任务','先明确目标'],['orange','使用工具','整理任务清单'],['cyan','输出','今日行动建议']]},
  coding:{name:'Coding 助手',project:'代码学习伙伴',question:'用一个例子解释循环。',answer:'循环就像每天给植物浇水：把“浇水”这个动作重复执行。你可以规定重复 5 次，也可以让它在“土壤还干燥”时继续。',blocks:[['yellow','当收到','编程问题'],['purple','扮演','友善的代码伙伴'],['blue','理解需求','先解释再实践'],['orange','使用工具','查看示例代码'],['cyan','输出','解释与改进建议']]},
  pi:{name:'Pi Agent',project:'探索型智能体',question:'一个智能体如何完成任务？',answer:'先理解目标，再决定是否需要工具；观察工具返回的结果，继续思考，直到可以给出答案。你可以在画布上查看和改造这个循环。',blocks:[['yellow','当收到','一个新目标'],['purple','设定角色','探索型智能体'],['blue','智能体循环','思考与行动'],['orange','使用工具','观察结果'],['cyan','完成','整理答案']]}
};
const categories=[['yellow','开始','触发','收到新消息'],['purple','角色','扮演','我的 AI 伙伴'],['blue','会思考','思考','拆解当前问题'],['green','会查找','查找','我的知识资料'],['pink','会记住','记住','重要偏好'],['orange','会行动','使用工具','完成一个步骤'],['cyan','会回答','回答','清楚地表达']];
let active='knowledge', blocks=[], selected=-1, mode='agent', running=false, timer, host, returnFocus;
function element(tag,cls,text){const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e;}
function toast(message){const box=document.querySelector('#toast');box.textContent=message;box.classList.add('visible');clearTimeout(box.dismiss);box.dismiss=setTimeout(()=>box.classList.remove('visible'),2600);}
export function mountDemo(){
host=document.querySelector('#studio');
host.innerHTML=`<header class="studio-header"><a class="brand" href="#" aria-label="返回 Blocky 官网"><img src="./assets/blocky.png" width="29" height="29" alt=""><span>Blocky.</span></a><span class="studio-demo-label">UI 交互演示 · 预设内容</span><a class="studio-back" href="#">返回官网</a></header>
<main class="studio-main" id="studio-main" tabindex="-1"><div class="studio-toolbar"><label class="blueprint-select-label">起始蓝图<select id="blueprint-select" aria-label="选择起始蓝图">${Object.entries(templates).map(([id,t])=>`<option value="${id}">${t.name}</option>`).join('')}</select></label><span class="project-title"></span><div class="studio-actions"><button class="icon-button" id="demo-help" aria-label="体验说明">?</button><button class="quiet-button" id="reset-demo">重置</button><button class="button button-accent button-small" id="run-demo">▷ 演示运行</button></div></div>
<div class="mobile-panels" aria-label="工作台面板"><button data-panel="library" aria-pressed="false">积木库</button><button data-panel="canvas" class="selected" aria-pressed="true">画布</button><button data-panel="chat" aria-pressed="false">对话</button></div>
<div class="studio-workspace" data-panel="canvas"><aside class="studio-library"><div class="panel-heading">积木库 <span>入门视图</span></div><p class="panel-hint">点击积木，加入画布</p><div class="palette"></div><div class="library-bottom">从一块积木开始<br>创造自己的方式</div></aside>
<section class="studio-canvas dotted" aria-label="积木画布"><div class="studio-canvas-bar"><span>◇ main</span><span class="canvas-count"></span></div><div class="demo-stack" aria-label="当前积木"></div><div class="block-editor" hidden><label for="block-value">积木参数</label><div><input id="block-value" maxlength="60" autocomplete="off"><button id="apply-block" class="quiet-button">应用</button><button id="remove-block" class="quiet-button">移除</button></div></div><div class="canvas-help">选择积木，可以编辑参数</div></section>
<aside class="studio-chat"><div class="chat-tabs" role="tablist" aria-label="对话模式"><button role="tab" id="tab-agent" aria-selected="true" aria-controls="chat-panel">Blocky Agent</button><button role="tab" id="tab-builder" aria-selected="false" aria-controls="chat-panel">构建助手</button></div><div id="chat-panel" role="tabpanel" aria-labelledby="tab-agent"><div class="demo-messages" aria-live="polite"></div><div class="demo-trace" aria-label="运行轨迹" hidden></div><div class="demo-composer"><button class="sample-question" id="sample-question"></button><form id="demo-form"><label class="sr-only" for="chat-input">输入演示消息</label><textarea id="chat-input" rows="2" maxlength="300" placeholder="输入一句话，看看对话界面…"></textarea><div class="composer-bottom"><span>预设回复 · 不调用模型</span><button type="submit" aria-label="发送演示消息">↑</button></div></form></div></div></aside></div>
<div class="studio-status"><span class="status-text">就绪 · 点击积木探索</span><span>仅在此页面展示，刷新后重置</span></div></main>
<dialog class="help-dialog"><div><h2>欢迎来到 Blocky</h2><p>这是一段可以点击探索的 UI 演示。</p><ol><li>选择四种蓝图，查看不同的创作起点。</li><li>点击积木库添加积木，再选择画布中的积木编辑参数。</li><li>点击“演示运行”查看预设轨迹，或切换构建助手。</li></ol><p class="muted">内容均为预设示例，不调用模型、不读写文件。你的输入只留在当前页面。</p><button class="button button-accent" id="close-help">开始探索</button></div></dialog>`;
host.querySelector('#blueprint-select').addEventListener('change',e=>selectTemplate(e.target.value));
host.querySelector('#reset-demo').addEventListener('click',()=>{selectTemplate(active);toast('演示已重置');});
host.querySelector('#run-demo').addEventListener('click',()=>running?stopRun():run());
host.querySelector('#apply-block').addEventListener('click',applyBlock);
host.querySelector('#block-value').addEventListener('keydown',e=>{if(e.key==='Enter')applyBlock();});
host.querySelector('#remove-block').addEventListener('click',()=>{stopRun(false);if(selected>=0){blocks.splice(selected,1);selected=-1;renderBlocks();host.querySelector('.block-editor').hidden=true;}});
host.querySelector('#tab-agent').addEventListener('click',()=>switchMode('agent'));
host.querySelector('#tab-builder').addEventListener('click',()=>switchMode('builder'));
host.querySelector('.chat-tabs').addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();switchMode(mode==='agent'?'builder':'agent');host.querySelector(mode==='agent'?'#tab-agent':'#tab-builder').focus();}});
host.querySelector('#demo-form').addEventListener('submit',e=>{e.preventDefault();sendMessage();});
host.querySelector('#sample-question').addEventListener('click',()=>{host.querySelector('#chat-input').value=mode==='agent'?templates[active].question:'帮我加入记忆能力';sendMessage();});
host.querySelector('#chat-input').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();sendMessage();}});
host.querySelectorAll('[data-panel]').forEach(button=>{if(button.tagName==='BUTTON')button.addEventListener('click',()=>setPanel(button.dataset.panel));});
const dialog=host.querySelector('dialog');host.querySelector('#demo-help').addEventListener('click',()=>{returnFocus=document.activeElement;dialog.showModal();});host.querySelector('#close-help').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>returnFocus?.focus());
categories.forEach(([color,name,verb,value])=>{const btn=element('button','palette-button');btn.style.setProperty('--category',`var(--${color})`);btn.append(element('span','palette-category',name),element('span','palette-description',verb+' · '+value));btn.addEventListener('click',()=>{if(blocks.length>=15){toast('演示画布最多展示 15 块积木');return;}stopRun(false);blocks.push([color,verb,value]);renderBlocks();setPanel('canvas');toast('已加入'+name+'积木');});host.querySelector('.palette').append(btn);});
selectTemplate(active);
}
function selectTemplate(id){if(!templates[id])return;stopRun(false);active=id;blocks=templates[id].blocks.map(b=>[...b]);selected=-1;host.querySelector('#blueprint-select').value=id;host.querySelector('.project-title').textContent=templates[id].project;host.querySelector('.block-editor').hidden=true;renderBlocks();switchMode(mode);host.querySelector('.status-text').textContent='就绪 · '+templates[id].name;}
function renderBlocks(){const stack=host.querySelector('.demo-stack');stack.replaceChildren();blocks.forEach(([color,verb,value],i)=>{const button=element('button',`block block-${color}${i===0?' cap':''}${i===selected?' block-selected':''}`);button.append(document.createTextNode(verb+' '),element('b','',value));button.setAttribute('aria-label',`${verb}：${value}，编辑积木`);button.setAttribute('aria-pressed',String(i===selected));button.addEventListener('click',()=>{selected=i;renderBlocks();const editor=host.querySelector('.block-editor');editor.hidden=false;host.querySelector('#block-value').value=blocks[i][2];host.querySelector('#block-value').focus();});stack.append(button);});if(!blocks.length)stack.append(element('p','canvas-empty','画布空了。去积木库加入你的第一块积木。'));host.querySelector('.canvas-count').textContent=`${blocks.length} 个积木`;}
function applyBlock(){const value=host.querySelector('#block-value').value.trim();if(selected<0||!value){toast('请填写积木参数');return;}blocks[selected][2]=value;renderBlocks();toast('参数已更新');}
function switchMode(next){stopRun(false);mode=next;host.querySelectorAll('[role="tab"]').forEach(tab=>{const yes=tab.id===`tab-${mode}`;tab.setAttribute('aria-selected',String(yes));tab.tabIndex=yes?0:-1;});host.querySelector('#chat-panel').setAttribute('aria-labelledby',`tab-${mode}`);host.querySelector('.demo-messages').replaceChildren();addMessage('assistant',mode==='agent'?`你好！我是${templates[active].project}。你可以试试下方的问题，看看对话与运行轨迹。`:'你好，我是 Blocky 构建助手。描述你的想法，一起看看画布可以怎样改变。');host.querySelector('#sample-question').textContent=mode==='agent'?templates[active].question:'帮我加入记忆能力';host.querySelector('#chat-input').value='';host.querySelector('.demo-trace').hidden=true;}
function addMessage(who,text){const message=element('div',`demo-message ${who}`);message.append(element('span','message-name',who==='user'?'你':mode==='agent'?'Blocky Agent':'构建助手'),element('p','',text));const box=host.querySelector('.demo-messages');box.append(message);box.scrollTop=box.scrollHeight;}
function sendMessage(){const input=host.querySelector('#chat-input');const value=input.value.trim();if(!value)return;stopRun(false);addMessage('user',value);input.value='';if(mode==='builder'){addMessage('assistant','示例修改：在画布中加入“记住学习偏好”积木。你可以点击它，继续编辑参数。');if(blocks.length<15){blocks.push(['pink','记住','学习偏好']);renderBlocks();}else{addMessage('assistant','画布已达到演示上限。移除一块积木后可以继续添加。');}}else{addMessage('assistant','预设回答示例：'+templates[active].answer);}host.querySelector('.status-text').textContent='演示回复完成 · 未调用模型';}
function setPanel(panel){host.querySelector('.studio-workspace').dataset.panel=panel;host.querySelectorAll('.mobile-panels button').forEach(btn=>{const yes=btn.dataset.panel===panel;btn.classList.toggle('selected',yes);btn.setAttribute('aria-pressed',String(yes));});}
function run(){if(!blocks.length){toast('请先加入一块积木');return;}stopRun(false);running=true;host.querySelector('#run-demo').textContent='□ 停止演示';const trace=host.querySelector('.demo-trace');trace.hidden=false;trace.replaceChildren(element('div','trace-caption','预设运行轨迹'));let index=0;function tick(){host.querySelectorAll('.demo-stack .block').forEach((b,i)=>b.classList.toggle('block-running',i===index));const item=element('div','demo-trace-step');item.append(element('span','',String(index+1).padStart(2,'0')),element('span','',blocks[index][1]+' · '+blocks[index][2]));trace.append(item);trace.scrollTop=trace.scrollHeight;host.querySelector('.status-text').textContent=`演示运行 ${index+1}/${blocks.length}`;index++;if(index<blocks.length){timer=setTimeout(tick,650);}else{timer=setTimeout(()=>{stopRun(false);addMessage('assistant','预设运行已完成。'+templates[active].answer);host.querySelector('.status-text').textContent='演示完成 · 未执行真实工具';setPanel('chat');},650);}}tick();}
export function stopRun(show=true){clearTimeout(timer);running=false;if(!host)return;host.querySelector('#run-demo').textContent='▷ 演示运行';host.querySelectorAll('.block-running').forEach(x=>x.classList.remove('block-running'));if(show)host.querySelector('.status-text').textContent='演示已停止';}
